/* Manual token entry globally resolves a record, including after a new browser session. */
async function confirmInstruction(request: Request) {
  const check = sensitive(request); if (check.failure) return check.failure;
  let input: any; try { input = await body(request); } catch { return error("Enter the testing mock reset token."); }
  const found = await findResetToken(input.value);
  const record = found.record;
  if (invalidRecord(record)) return error("This reset instruction is invalid, expired, or already used. You can request a new one.");
  if (record.tokenLockUntil > now()) return locked();
