const RESET_MS = 15 * 60 * 1000;
const MFA_MS = 10 * 60 * 1000;
const LOCK_MS = 5 * 60 * 1000;
const BODY_LIMIT = 8192;
const RESET_FAILURE_LIMIT = 5;
const now = () => Date.now();

