  if (value.length > 128) return "Use no more than 128 characters.";
  return /[a-z]/.test(value) && /[A-Z]/.test(value) && /[0-9]/.test(value) && /[^A-Za-z0-9]/.test(value)
    ? "" : "Use an uppercase letter, lowercase letter, number, and symbol.";
}
