}
function clearConfirmationFailures(session: any) {
  session.resetConfirmationFailures = { count: 0, lockUntil: 0 };
}

/* Reset records are globally resolved by hash. This read helper has no session mutation. */
function resetRecord(session: any) {
  const hash = session?.recovery?.tokenHash;
  const record = hash && resetTokens.get(hash);
  return record && !record.used && record.expiresAt > now() ? record : undefined;
}
function attachRecovery(session: any, tokenHash: string, record: any) {
